import{z as B,x as s,o as t,c as p,q as n,j as A,D as E,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"远期溢价之谜","description":"","frontmatter":{"title":"远期溢价之谜","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/forward-premium-puzzle.md","filePath":"econ/forward-premium-puzzle.md","lastUpdated":1791413859000}'),d={name:"econ/forward-premium-puzzle.md"};function m(P,a,u,F,C,I){const l=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="远期溢价之谜" tabindex="-1">远期溢价之谜 <a class="header-anchor" href="#远期溢价之谜" aria-label="Permalink to &quot;远期溢价之谜&quot;">​</a></h1><div class="epigraph"><p>高利率货币倾向升值而不是按 UIP 贬值；Fama 回归的斜率常为负。这是风险溢价、还是预期误差，要分开写，不要把 CIP 复制失败误读成这一句。</p><footer>—— Fama, Forward and Spot Exchange Rates, JME 1984；对照 Engel 综述</footer></div><p><a href="/econ/exchange-rate-disconnect">上一课</a>给出汇率与宏观脱节。本课把资产平价的偏差写细：远期溢价之谜。国际风险分担下一课换数量（消费）。主干<a href="/econ/uip-and-cip">UIP 与 CIP</a> 已拆两句；本课只补 UIP 的回归斜率，实证细节与基差仍见 <code>/quant/irp</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UIP：\\(\\mathbb{E}[\\Delta e]=i-i^*\\)。Fama：把 \\(\\Delta e\\) 对远期溢价（或利差）回归，斜率 \\(\\beta=1\\) 为 UIP。估计常显著小于 1，甚至为负：高息货币随后升值，套息有平均利润。缺口不是再写 CIP 公式——CIP 是覆盖套利，谜是无抛补。分解：\\(\\beta\\neq 1\\) 来自时变风险溢价（与利差相关）或预期系统性错误（学习、比索）。两者观测上纠缠。</p><p><span class="marginnote">比索问题：小概率大贬值未在样本实现，利率含这笔溢价，样本内高息货币「不贬」。这是小样本，不是偏好。</span></p><p><span class="marginnote">UIP（无抛补利率平价）翻译成大白话：两国利差应被汇率变化抵消——高利率货币该贬值，让「先换过去吃利息、再换回来」的人占不到便宜。它不是银行报价规则，而是关于预期的无套利猜想，所以只能用数据统计检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宏观主干只保留：UIP 是期望假说，失败改变蒙代尔装置里 \\(i=i^*+\\mathbb{E}\\Delta e\\) 的定量，不取消三角的逻辑。风险溢价：\\(m\\) 与 \\(\\Delta e\\) 的条件协方差。套息作为策略的夏普在量化栏；本课不写交易规则、不写杠杆、不进簿。Habit、长期风险、稀有灾难可以把溢价做大，定量是否匹配 Fama 斜率仍争。</p>',9)),(t(),A(o,null,{default:E(()=>[i(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20UIP%5B%22UIP%3A%20%CE%B2%20%3D%201%22%5D%20--%3E%20FAMA%5B%22Fama%3A%20%CE%B2%20%E5%B8%B8%20%EF%BC%9C%201%20%E7%94%9A%E8%87%B3%E8%B4%9F%22%5D%0A%20%20RP%5B%22%E6%97%B6%E5%8F%98%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%20--%3E%20FAMA%0A%20%20EXP%5B%22%E9%A2%84%E6%9C%9F%E8%AF%AF%E5%B7%AE%20%2F%20%E6%AF%94%E7%B4%A2%22%5D%20--%3E%20FAMA%0A%20%20CIP%5B%22CIP%20%E5%A4%8D%E5%88%B6%22%5D%20--%3E%20Q%5B%22%2Fquant%2Firp%2C%20%E4%B8%8D%E6%98%AF%E6%9C%AC%E8%B0%9C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与脱节：预报失败与 UIP 失败相关但不是同一检验。游走赢宏观模型，不等于套息一定赢（还有波动与崩断）。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"套息交易像「借低息的钱、存高息的银行」：多数年份稳稳赚利差，但一旦高息货币突然大跌（1998 年日元、2008 年危机），几个月的利润一夜亏光。收益结构是「在压路机前捡钢镚」：平均为正，极端巨亏。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是补偿或误预期。风险：投资高息货币的坏状态与随机折现因子同向，要求超额回报，利差高时溢价更高，可以把 \\(\\beta\\) 拉到负。误预期：投资者对均值回归过慢。政策：利率规则若对汇率反应，利差与未来 \\(\\Delta e\\) 的联合分布改，Lucas 批判适用。",-1)),a[7]||(a[7]=e("p",null,"危机后 CIP 破裂是中介约束，把抛补都打开；与经典 Fama 谜分层。不要用 2008 年后的基差「解释」1980 年代的负斜率。",-1)),(t(),A(o,null,{default:E(()=>[i(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E5%80%9F%E4%BD%8E%E6%81%AF%E8%B4%A7%E5%B8%81%20%E6%8A%95%E9%AB%98%E6%81%AF%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20WIN%5B%22%E5%A4%9A%E6%95%B0%E6%97%B6%E5%80%99%E9%AB%98%E6%81%AF%E8%B4%A7%E5%B8%81%E4%B8%8D%E8%B4%AC%22%5D%0A%20%20WIN%20--%3E%20PROF%5B%22%E5%90%83%E5%88%A9%E5%B7%AE%E4%B8%8E%E5%8D%87%E5%80%BC%20%E5%A5%97%E6%81%AF%E5%88%A9%E6%B6%A6%22%5D%0A%20%20RISK%5B%22%E5%B0%8F%E6%A6%82%E7%8E%87%E9%AB%98%E6%81%AF%E8%B4%A7%E5%B8%81%E6%80%A5%E8%B4%AC%22%5D%20--%3E%20CRASH%5B%22%E5%B4%A9%E6%96%AD%20%E6%95%B0%E6%9C%88%E5%88%A9%E6%B6%A6%E4%B8%80%E6%AC%A1%E4%BA%8F%E5%85%89%22%5D%0A%20%20CRASH%20--%3E%20RP%5B%22%E8%B4%9F%E5%81%8F%E6%94%B6%E7%9B%8A%E8%A6%81%E6%B1%82%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20RP%20--%3E%20FAMA%5B%22Fama%20%E6%96%9C%E7%8E%87%E4%B8%BA%E8%B4%9F%E7%9A%84%E4%B8%80%E7%A7%8D%E8%A7%A3%E9%87%8A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">常见误区：把 2008 年后远期报价偏离 CIP 当成 UIP 之谜被解决。两者不同层：CIP 是有风险对冲时的报价关系，偏离来自银行资产负债表约束；UIP 是带预期的无套利，谜从 1980 年代就在。别拿一个去解释另一个。</span></p><p><span class="marginnote">Engel：难题是风险溢价必须既大又与利差强相关，标准模型的 \\(m\\) 往往不够。这与股权溢价之谜同族，对象换成货币。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不报套息的历史夏普。不把负斜率写成套利机会无风险——崩断与利差收窄会吃掉。下一课风险分担：完全市场下相对消费与 \\(q\\) 应锁；那是数量谜，本课是价格谜。不要重写 CIP。不要用本课去给交易员写手册。</p><p>后课默认：Fama \\(\\beta\\neq 1\\) 是 UIP 失败，候选是风险溢价与预期误差；CIP 是另一句。蒙代尔用 \\(i=i^*\\) 是退化，定量上要加溢价。风险分担下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fama 回归检验 UIP；斜率常小于 1 甚至为负。</li><li>高息货币平均升值 = 套息利润，含崩断风险。</li><li>风险溢价与比索 / 学习纠缠。</li><li>CIP 偏离不是本谜；见量化栏。</li><li>出处：Fama, <em>JME</em> 1984；Engel 综述；比索问题传统。</li></ul>',7))])}const c=B(d,[["render",m]]);export{f as __pageData,c as default};
